package com.orderflow.notification.service;
import com.orderflow.events.*;import com.orderflow.notification.config.KafkaTopicProperties;import com.orderflow.notification.domain.*;import com.orderflow.notification.outbox.OutboxStore;import com.orderflow.notification.repository.*;import io.micrometer.core.instrument.MeterRegistry;import java.time.*;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.support.*;
@Service public class NotificationWorkflowService{static final String CONSUMER="notification-domain-events-v1";private final NotificationRepository notifications;private final NotificationPreferenceRepository preferences;private final NotificationDeliveryRepository deliveries;private final ProcessedEventStore processed;private final NotificationTemplateService templates;private final NotificationMapper mapper;private final AsyncNotificationFanout fanout;private final OutboxStore outbox;private final KafkaTopicProperties topics;private final MeterRegistry metrics;private final Clock clock;public NotificationWorkflowService(NotificationRepository n,NotificationPreferenceRepository p,NotificationDeliveryRepository d,ProcessedEventStore s,NotificationTemplateService t,NotificationMapper m,AsyncNotificationFanout f,OutboxStore o,KafkaTopicProperties k,MeterRegistry r,Clock c){notifications=n;preferences=p;deliveries=d;processed=s;templates=t;mapper=m;fanout=f;outbox=o;topics=k;metrics=r;clock=c;}
 @Transactional public void process(EventMetadata metadata,UUID user,NotificationType type){if(processed.contains(metadata,CONSUMER))return;if(notifications.existsByUserIdAndTypeAndSourceEventId(user,type,metadata.eventId())){processed.add(metadata,CONSUMER);return;}Instant now=Instant.now(clock);var t=templates.template(type);Notification n=notifications.saveAndFlush(new Notification(user,type,t.title(),t.message(),metadata.eventId(),metadata.aggregateId(),now));preferences.findById(user).ifPresent(p->{if(p.isEmailEnabled())dispatch(n,p.getEmailAddress(),NotificationChannel.EMAIL,metadata,now);if(p.isSmsEnabled())dispatch(n,p.getPhoneNumber(),NotificationChannel.SMS,metadata,now);});processed.add(metadata,CONSUMER);metrics.counter("notifications_created_total","type",type.name()).increment();var response=mapper.response(n);if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){fanout.publish(user,response);}});}
 private void dispatch(Notification n,String destination,NotificationChannel channel,EventMetadata cause,Instant now){NotificationDelivery d=deliveries.save(new NotificationDelivery(n.getId(),channel,destination,now));EventMetadata m=new EventMetadata(UUID.randomUUID(),EventType.NOTIFICATION_DISPATCH_REQUESTED,1,"NOTIFICATION",n.getId(),now,cause.correlationId(),cause.eventId(),"notification-service");outbox.enqueue(topics.notificationEvents(),n.getId(),new NotificationDispatchRequestedEvent(m,n.getId(),n.getUserId(),channel.name(),d.getId()),m);}
}
